@@ -0,0 +1,12 @@
+import { createEventCard } from './event-card.js';
+
+export function sortEventsChronologically(events) {
+  return events
+    .map(event => ({ event, timestamp: new Date(event.startsAt).getTime() }))
+    .sort((left, right) => left.timestamp - right.timestamp)
+    .map(({ event }) => event);
+}
+
+export function buildAgenda(events) {
+  return sortEventsChronologically(events).map(createEventCard);
+}

